lized\n# Note: \"reversing the order\" means the first element becomes Hartford, second becomes New Haven\nQ_hartford = hartford_1943 / (new_haven_1943 + hartford_1943)  # Same normalization, but position swapped\nQ_new_haven = new_haven_1943 / (new_haven_1943 + hartford_1943)\nQ = [Q_hartford, Q_new_haven]\n\nprint(\"Distribution P (New Haven, Hartford):\", P)\nprint(\"Distribution Q (Hartford, New Haven - reversed):\", Q)\n\n# Calculate KL divergence D_KL(P || Q) = Σ P_i * log(P_i / Q_i)\n# Note: P is in order [NewHaven, Hartford]\n# Q is in order [Hartford, NewHaven] - so Q[0] corresponds to Hartford value at position 0\n# Wait, let me reconsider...\n\n# Actually, when we reverse the order:\n# P = [New Haven normalized, Hartford normalized]\n# Q = [Hartford normalized, New Haven normalized]\n\n# So we compare:\n# P[0] = New Haven value, Q[0] = Hartford value (reversed positions!)\n# P[1] = Hartford value, Q[1] = New Haven value (reversed positions!)\n\n# Let's calculate properly\nD_KL = sum(P[i] * math.log(P[i] / Q[i]) for i in range(len(P)))\n\nprint(f\"\\nD_KL(P || Q) = {D_KL:.5f}\")\nprint(f\"More precisely: {D_KL}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
